  "WB":  [2, 1, 8],
  "LN":  [1, 0.5, 2],
  "WP":  [115, 40, 300],
  "LP":  [0.5, 0.3, 1.0],
  "WPB": [4.6, 1.5, 15],
  "WPC": [40, 10, 150],
  "LPC": [0.3, 0.15, 0.8],
  "WNC": [10, 3, 50],
  "LNC": [0.3, 0.15, 0.8],
  "WNM": [16, 4, 60],
